INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ea9e280f-5893-5191-a444-14ce94fa08ec', '2e1400b6-0df2-5a23-bbd8-c0dc47f1143e', 'ats', 'electrical', '2', 'Perform insulation-resistance tests for one minute on each bus section, phase-to-phase and phase-to-ground. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('de3218f6-12cb-5e06-b216-d2d05260d3a8', '2e1400b6-0df2-5a23-bbd8-c0dc47f1143e', 'ats', 'electrical', '3', 'Perform a dielectric withstand voltage test on each bus section, each phase-to-ground with phases not under test grounded, in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.2. The test voltage shall be applied for one minute. Refer to Section 7.13 before performing tests.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('19832ac6-ecfa-5aed-b8c0-4066676cd6c8', '2e1400b6-0df2-5a23-bbd8-c0dc47f1143e', 'ats', 'electrical', '4', 'Perform insulation-resistance tests on control wiring with respect to ground. Applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components or control devices that cannot tolerate the applied voltage, follow the manufacturer’s recommendation.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
