INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1843102f-660d-54d8-9fc3-b96303f3285a', 'faa84834-8462-568f-a8bc-a01378b731c2', 'mts', 'test_value_electrical', '4', 'Power-factor or dissipation-factor tip-up exceeding 1.0 percent should be investigated.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('45239749-b017-56c3-87cd-3a0a30994d13', 'faa84834-8462-568f-a8bc-a01378b731c2', 'mts', 'test_value_electrical', '5', 'Turns-ratio test results should not deviate more than one-half percent from either the adjacent coils or the calculated ratio.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d73e5aeb-d241-508c-b90c-3d97c3c664f9', 'faa84834-8462-568f-a8bc-a01378b731c2', 'mts', 'test_value_electrical', '6', 'The typical excitation current test data pattern for a three-legged core transformer is two similar current readings and one lower current reading. The test should produce a pattern typical for the specific transformer type and configuration.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
