INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('6bc3e421-bb1e-56ab-99ac-d277e068c856', 'faa84834-8462-568f-a8bc-a01378b731c2', 'mts', 'test_value_electrical', '11', 'Test results for surge arresters shall be in accordance with Section 7.19.', false, 10) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
