INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('6c676e06-e033-5a6e-9b5f-332a402ccd46', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'electrical', '4', 'Perform a jacket integrity test for one minute. Use voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s data use a minimum of 2 kV for cables up to 35 kV and minimum of 5 kV for cables rated higher than 35 kV.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4dceb373-d309-576a-a53f-94708a4e2237', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'electrical', '5', 'Perform a dielectric withstand test using one or more of the following methods. Note the voltage may need to be limited due to power supply chosen and cable terminations, splices, and accessories.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('196b49c3-6545-5372-8b88-22d5fb26105a', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'electrical', '6', 'Perform a tan-delta (insulation power factor/dissipation factor) test on each individual conductor with all shields and all conductors not under test grounded. In the absence of cable and accessory manufacturers’ published data see Table 100.6.6 and Table 100.6.7. Record stability and mean tan-delta values at each step.', true, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f85662bb-70d5-509b-a2ce-73d3dee838d9', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'electrical', '7', 'Perform an online partial discharge (PD) test. Record ambient noise floor, waveform, and phase-resolved PD pattern of any PD detected.', true, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('bc537b21-cb11-53a3-b714-630581a79212', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'electrical', '8', 'Perform an offline partial discharge (PD) test. Record average or peak ambient background noise floor, PD calibration pulse, and any relevant PD, notating location, amplitude, repetition, PD inception, PD extinction voltage thresholds for cable and accessories, and phase resolved pattern. Follow cables and accessory manufacturers’ published data for cable accessories, any connected equipment, and test equipment. In the absence of cable and accessory manufacturers’ published data see Table 100.6.3, 100.6.4, and 100.6.5 for maximum voltage levels.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3c47d36c-605b-5a57-ba35-e20c5b78018b', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_visual', '1', 'Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.12. (7.3.3.A.3)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e056e157-bab8-5c5d-b1ab-130d9363cb67', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_visual', '2', 'Results of the thermographic survey shall be in accordance with Section 9. (7.3.3.A.10)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('77133d89-e0bc-5aa3-b971-15b1f21cc11a', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_visual', '3', 'Cable bends should not be less than ICEA and/or manufacturer''s minimum allowable bending radius. In the absence of manufacturer''s data refer to Table 100.22. The minimum bend radius to which insulated cables may be bent for permanent training shall be in accordance with Table 100.22. (7.3.3.A.6)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('5cda735f-def8-5649-ba73-3a7c8c691145', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '1', 'Insulation-resistance values should be in accordance with manufacturer’s published data. Conductor and insulation geometry, temperature, and overall cable length need to be taken into account in accordance with manufacturer’s published data for definitive minimum insulation resistance criteria.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('6b3081f9-4ff3-548f-94a0-93ac8c99e970', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '2', 'Shielding shall exhibit continuity. Investigate resistance values in excess of ten ohms per 1000 feet of cable.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('16b7a995-cfe2-55fc-98c6-84913129c687', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '3', 'TDR graphical measurements shall clearly identify the cable length and characteristic should be consistent with other phases.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('fc5cb164-65fe-5c32-a79a-b1dc5adfb396', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '4', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the test, the test specimen is considered to have passed the test.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('a3bad8b1-e388-5d7a-ab4f-f058b987712a', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '5', 'If no evidence of distress (distortion of applied waveform, overload/trip) or insulation failure is observed by the end of the total time of voltage application during the test, the test specimen is considered to have passed the test.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2c3ae6ae-33ae-5af7-a1b3-4cab24d71ee8', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '6', 'For evaluation of tan-delta results see Table 100.6.7 or IEEE 400.2.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('9dd750a8-48f1-5400-bf10-afd52cbef168', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '7', 'There should be no evidence of partial discharge during online testing. Any environmental background noise should be filtered out or eliminated from the reported PD measurements. Record any PD originating from the cable, including amplitude, repetition, and phase pattern of PD relative to the system voltage, to help determine internal, surface, and corona type PD.', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('fff848b3-e0fa-5cfa-a8f2-cba31c71fb5c', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'ats', 'test_value_electrical', '8', 'There shall be no evidence of offline partial discharge at or below the PD voltage threshold limits in accordance with manufacturer’s published data or IEEE 400.3. ---', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('531d453b-9dec-5a20-bf27-eea6867a3fee', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '1', 'Inspect exposed sections of cables and connectors for physical damage and evidence of degradation and corona.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('777542fa-7b4f-5a0c-a418-7456330272c9', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '2', 'Inspect terminations and splices for physical damage, evidence of overheating, and corona.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('98cbd3cc-1216-5e60-a958-3536f12ea699', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '3', 'Inspect bolted electrical connections for high resistance using one or more of the following:', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1b046f1e-9c7a-55fb-a611-f35a51ed4629', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '4', 'Inspect shield grounding and cable support.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('7758dec1-73cd-5eef-8b1d-7f0a103ece84', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '5', 'Verify that visible cable bends are not less than ICEA and/or manufacturer’s minimum allowable bending radius.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ccc60887-bdc7-5089-9bf3-784ed546c56f', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '6', 'Inspect fireproofing in common cable areas.', true, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4aaa63ed-e487-5c16-90c3-5a2a521a89a6', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '7', 'If cables are terminated through window-type current transformers, inspect to verify that neutral and ground conductors are correctly placed and that shields are correctly terminated for operation of protective devices.', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d2f0584a-fa78-58fe-b26c-26ff7a9e1936', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'visual_mechanical', '8', 'Compare cable data with drawings and cable schedule.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('136d34c5-4eea-5121-a684-4a4e8259c58b', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '1', 'Perform resistance measurements through bolted connections with a low-resistance ohmmeter in accordance with Section 7.3.3.A.3.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('db6aace8-9cb4-5f0d-b516-4c2883f20160', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '2', 'Perform an insulation-resistance test individually between each phase/conductor and its shield with all other phase/conductors and shields grounded. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c5c91846-3a86-5956-a69a-9f5587e875e4', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '3', 'Perform a shield-continuity test on each power cable by ohmmeter method.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c7ad280e-e6b3-5e6b-aa03-e10bad20440d', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '4', 'Perform a jacket integrity test for one minute. Use voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s data use a minimum of 2 kV for cables up to 35 kV and minimum of 5 kV for cables rated higher than 35 kV.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('42fc673e-88ae-5623-bda7-2c33b87296fb', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '5', 'In accordance with ICEA, IEC, IEEE and other power cable consensus standards, and manufacturer’s published data, testing can be performed by means of direct current, power frequency alternating current, very low frequency alternating current, or damped alternating current. These sources may be used to perform insulation withstand tests and diagnostic tests such as partial discharge analysis and tan delta (or power factor). The selection can only be made after an evaluation of the available test methods, manufacturer’s published data, and a review of the installed cable system.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('80fb3a55-f174-5f60-84d1-34a706a944d7', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '6', 'Perform a dielectric withstand test using one or more of the following methods. Note the voltage may need to be limited due to power supply chosen and cable terminations, splices, and accessories.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('41c579d7-5302-5973-8fab-614b43e0473d', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '7', 'Perform a tan-delta (insulation power factor/dissipation factor) test on each individual conductor with all shields and all conductors not under test grounded. In the absence of manufacturer’s published data see Table 100.6.6 and Table 100.6.7. Record stability and mean tan-delta values at each step.', true, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0b4d111a-3b2f-5f45-af8a-e6e34e02e48f', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '8', 'Perform an online partial discharge (PD) test. Record ambient noise floor, waveform, and phase-resolved PD pattern of any PD detected.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c8cafcb7-c4f2-5b1a-9bc3-59792869d2a0', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'electrical', '9', 'Perform an offline partial discharge (PD) test. Record average or peak ambient background noise floor, PD calibration pulse, and any relevant PD, notating location, amplitude, repetition, PD inception, PD extinction voltage thresholds for cable and accessories, and phase resolved pattern. Follow manufacturer’s published data for cable accessories, any connected equipment, and test equipment. In the absence of manufacturer’s published data see Table 100.6.3, 100.6.4, and 100.6.5 for maximum voltage levels.', true, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c056ca0a-e24a-5e17-a026-a2f89c12dc42', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'test_value_visual', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value. (7.3.3.A.3.1)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3ce59b46-9ec0-56fa-a2e0-d56a9fd73304', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'test_value_visual', '2', 'Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.12. (7.3.3.A.3.2)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('49996ca3-b410-567f-a13f-6faf3e38c09a', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'test_value_visual', '3', 'Results of the thermographic survey shall be in accordance with Section 9. (7.3.3.A.3.3)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
