INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f89884c2-b818-5d2b-aa20-8216d0e8a23f', '2d6d9119-ee9b-536a-abe6-bc9845fa7567', 'mts', 'test_value_electrical', '4', 'If no evidence of distress (distortion of applied waveform, overload/trip) of insulation failure is observed by the end of the total time of voltage application during the test, the test specimen is considered to have passed the test.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
