INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('40908ea8-d77d-519c-9dc0-c6d3be3f517a', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '1', 'Perform resistance measurements through bolted connections and bus joints with a lowresistance ohmmeter in accordance with Section 7.4.A.3.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3f5db7fc-f91f-50fd-b587-48f06a0cfcef', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '2', 'Perform insulation resistance tests on each busway for one minute, phase-to-phase and phase-to-ground. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('31309c3e-5c0b-58b7-8118-8a0628647ea5', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '3', 'Perform a dielectric withstand voltage test on each busway, phase-to-ground with phases not under test grounded, in accordance with manufacturer’s published data. If manufacturer has no recommendation for this test, it shall be in accordance with Table 100.17. Where no DC test value is shown in Table 100.17, an AC value shall be used. The test voltage shall be applied for one minute.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('273d1026-b209-5011-b68a-75e5bfe34061', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '4', 'Perform a contact-resistance test on each accessible connection point of uninsulated busway and compare values with the adjacent phases.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e1d31101-fa5e-56a8-8dd4-d2cd6ebca580', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '5', 'Perform a contact-resistance test on assembled sections of insulated busways and compare values with the adjacent phases.', true, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3dd89927-e056-5f46-b016-56112b99c4fe', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '6', 'Verify operation of busway space heaters', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('a0febf81-59c8-5c58-ba14-ecc932dccc26', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'electrical', '7', 'Perform online partial-discharge survey in accordance with Section 11.', true, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f68b5dda-eebb-537c-b679-c1f9ce95464e', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'test_value_visual', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value. (7.4.A.3.1) 2 Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.12. (7.4.A.3.2)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1ef66412-5d31-550c-b3b3-b292b427f413', 'bd3d5f54-1c37-50f9-9c6e-84396280e3db', 'mts', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value. 2.1 Low-Voltage Metal-Enclosed Busways - Insulation-resistance test voltages and minimum insulation resistance values shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, insulation resistance values are to be corrected to a nominal 100-foot busway run. Use the following formula to determine the minimum insulation resistance value, in Megohms, to a 100-foot nominal value: Minimum Megohm Value = 100 ÷ [busway length in feet] Adjusted 1000 ft Nominal Value = measured insulation resistance x (Length of Run/1000) Converted values of insulation resistance less than manufacturer’s minimum or less than the corrected minimum Megohm value should be investigated. Dielectric withstand voltage tests should not proceed until insulation-resistance levels are raised above minimum values. 2.2  Medium-Voltage Metal-Enclosed Busways – Insulation-resistance test voltages and resistance values shall be in accordance with the manufacturer’s published data or Table 100.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2891dee3-941f-5b76-b1ab-322c6d6d3160', 'd855d8ac-e2e4-5ad7-8f29-6165a9ebf107', 'ats', 'visual_mechanical', '1', 'Compare equipment nameplate data with drawings.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
