INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('bf3df97e-303b-529d-8800-10592a20fe5f', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '2', 'Perform a contact/pole-resistance test.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('62aab367-8e05-5f08-8099-7a0abbdcd4cf', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '3', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phase-to-ground with switch closed, and across each open pole. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d915f4d6-ff12-5e2f-8946-95f92daaa809', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '4', 'Perform insulation-resistance tests on all control wiring with respect to ground. Applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components or control devices that cannot tolerate the applied voltage, follow manufacturer’s recommendation.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('7ce3bc61-fcaf-5da9-b221-999eb3c1e4a8', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '5', 'Perform a dielectric withstand voltage test on each pole with switch closed. Test each pole-to-ground with all other poles grounded. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.19.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('906935b6-5f8d-54fc-a224-3ff84c5990d9', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '6', 'Remove a sample of insulating liquid in accordance with ASTM D 923. Sample shall be tested in accordance with the referenced standard.', true, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2bbbfbef-8630-5f81-a270-c3450cc41c8e', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'electrical', '7', 'Measure fuse resistance.', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
