INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4753b5d9-8f1d-5ecc-8b3b-2b4a15849618', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_visual', '2', 'Results of the thermographic survey shall be in accordance with Section 9. (7.5.2.A.14)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4e94b617-64f3-556c-ba1b-5ffc93820be5', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_visual', '3', 'Operation counter shall advance one digit per close-open cycle. (7.5.2.A.13)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('01c965a2-05af-5e36-aa98-8c2aaac6a1d1', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('5ef8137c-c4de-57cc-b3f5-2d95adaa57bb', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_electrical', '2', 'Microhm or dc millivolt drop values shall not exceed the high levels of the normal range as indicated in the manufacturer’s published data. If manufacturer’s data is not available, investigate values that deviate from adjacent poles or similar switches by more than 50 percent of the lowest value.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f5576ef8-29f3-5ae4-8fd2-828074521983', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_electrical', '3', 'Insulation-resistance values shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations shall be investigated. Dielectric withstand voltage tests should not proceed until insulation-resistance levels are raised above minimum values.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('04cb2d6b-54aa-582e-9836-62038166fde1', 'b22aff03-375c-5583-b7e8-f28357876b87', 'ats', 'test_value_electrical', '4', 'Insulation-resistance values of control wiring shall not be less than two megohms.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
