INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('44b1d130-7614-515e-ac9c-71c5568a4967', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'electrical', '1', 'Perform resistance measurements through bolted connections with a low-resistance ohmmeter in accordance with Section 7.5.2.A.11.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('749ea5de-f664-5e5f-ab56-99caf327d0cc', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'electrical', '2', 'Perform a contact/pole-resistance test.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f6b7e042-7bf6-5277-a509-375870c5e7de', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'electrical', '3', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phaseto-ground with the switch closed, and across each open pole. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0d1beafa-33c5-5bd0-9299-7a27f921b69b', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'electrical', '4', 'Perform insulation-resistance tests on all control wiring with respect to ground. The applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components or control devices that cannot tolerate the applied voltage, follow manufacturer’s recommendation.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('8daedbba-4493-5894-9876-85dbec892166', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'electrical', '5', 'Perform a dielectric withstand voltage test on each pole with switch closed. Test each poleto-ground with all other poles grounded. Test voltage shall be in accordance with manufacturer’s published data or Table 100.19. *6 Remove a sample of insulating liquid in accordance with ASTM D923. Sample shall be tested in accordance with the referenced standard.', true, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('8c72b700-7199-5fd6-9ac6-414b233ab426', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_visual', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value. (7.5.2.A.11.1)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0af0d8e1-ee9a-50a9-973e-e529e9fedf62', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_visual', '2', 'Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.12. (7.5.2.A.11.2)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4d2ce05b-6d73-5820-9963-633d4fc7f97c', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_visual', '3', 'Results of the thermographic survey shall be in accordance with Section 9. (7.5.2.A.11.3)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('9810730d-91d1-5eef-9083-c61b62d74fdf', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_visual', '4', 'Operations counter should advance one digit per close-open cycle. (7.5.2.A.16)', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('cdb43b58-b249-5e24-b1f2-0f832b6c1ec3', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('fd136034-663e-5f7e-a0bc-cf8cbfa57dc1', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '2', 'Microhm or dc millivolt drop values should not exceed the high levels of the normal range as indicated in the manufacturer’s published data. If manufacturer’s data is not available, investigate values that deviate from adjacent poles or similar switches by more than 50 percent of the lowest value.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2ad1a5b9-d900-5f5c-8435-79316062d1b9', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '3', 'Insulation-resistance values should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated. Dielectric withstand voltage tests should not proceed until insulation-resistance levels are raised above minimum values.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('a37d9a72-e36b-5ee4-8ba3-60e1045cbf85', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '4', 'Insulation-resistance values of control wiring should be comparable to previously obtained results but not less than two megohms.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('eccd125c-3b24-53ce-a439-593727fcf8a2', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '5', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the dielectric withstand voltage test, the test specimen is considered to have passed the test.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2f53e2f2-12ed-583e-a3e5-679607fb9c8c', 'b22aff03-375c-5583-b7e8-f28357876b87', 'mts', 'test_value_electrical', '6', 'Insulating liquid test results should be in accordance with Table 100.4.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
