INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('a7c549c6-e350-529b-bb6b-adbf2d60108a', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_visual', '1', 'Critical distances of the operating mechanism shall be in accordance with manufacturer’s published data. (7.5.3.A.7)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
