INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('24246485-2c5e-5823-8b65-ee7506b1cb26', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_visual', '3', 'Results of the thermographic survey shall be in accordance with Section 9. (7.5.3.A.15)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('af41067f-4157-5a25-8c10-a2df036b0dfb', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_visual', '4', 'Operation counter shall advance one digit per close-open cycle. (7.5.3.A.14)', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('8340b10a-c258-5e0c-adac-bd9df5269a6f', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('6b05c049-acaf-5597-86b3-e2614c2a6be1', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_electrical', '2', 'Microhm or dc millivolt drop values shall not exceed the high levels of the normal range as indicated in the manufacturer’s published data. If manufacturer’s data is not available, investigate values that deviate from adjacent poles or similar switches by more than 50 percent of the lowest value.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3d0d11ce-daae-5ee7-bf99-84ff3b91cc21', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_electrical', '3', 'Insulation-resistance values shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated. Dielectric withstand voltage tests shall not proceed until insulation-resistance levels are raised above minimum values.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('26c7ae4c-a6f1-58ef-9a4c-ea7279d99fc3', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_electrical', '4', 'In the absence of manufacturer’s published data, each vacuum interrupter pressure shall not be greater than 1x10-2 Pa and shall not deviate from adjacent poles by more than two orders of magnitude.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c285a545-2593-559a-966e-110d5edda561', '50e59244-3baa-5d9d-b8c7-fa29f7ee6de0', 'ats', 'test_value_electrical', '5', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the vacuum bottle integrity test, the test specimen is considered to have passed the test.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
