INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2dbc11fb-ed22-50e0-bceb-20338b3dc632', '8e1fffda-52f3-58a4-84c1-466bb4486108', 'mts', 'test_value_electrical', '2', 'Insulation-resistance values of breakers should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
