INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('5709056c-e974-506b-bdc3-003d9842bf2e', '183941bb-f86a-549c-aa5d-46712a24a78b', 'ats', 'electrical', '9', 'Measure blowout coil circuit resistance.', false, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
