INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e227d8e5-0eea-5f91-a2e7-a95e3a72b1fc', '183941bb-f86a-549c-aa5d-46712a24a78b', 'ats', 'test_value_electrical', '1', 'Insulation-resistance values of circuit breakers shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1ad8c309-0cba-5748-befe-6362aed2a4a6', '183941bb-f86a-549c-aa5d-46712a24a78b', 'ats', 'test_value_electrical', '2', 'Microhm or dc millivolt drop values shall not exceed the high levels of the normal range as indicated in the manufacturer’s published data. In the absence of manufacturer’s data, investigate values that deviate from adjacent poles or similar breakers by more than 50 percent of the lowest value.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
