INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('5d2808bf-1988-5e77-bf3e-7274074d73ea', '183941bb-f86a-549c-aa5d-46712a24a78b', 'ats', 'test_value_electrical', '4', 'Breaker mechanism charge, close, open, trip, trip-free, and antipump features shall function as designed.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
