INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('13b3fdc8-ab08-537c-8919-5f7ff84d8349', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '1', 'Perform resistance measurements through bolted connections with a low-resistance ohmmeter. See Section 7.6.1.3.A.11.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d54c7e6e-c6cd-58e5-8c31-c2593ec504c3', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '2', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phaseto-ground with the circuit breaker closed, and across each open pole. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e92a4be8-63c5-5a60-895a-6989780d23aa', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '3', 'Perform insulation-resistance tests on all control wiring with respect to ground. The applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components or control devices that cannot tolerate the applied voltage, follow manufacturer’s recommendation.', true, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('b2c4a4ea-90dc-5d30-a99d-674988da6c3c', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '4', 'Perform a static contact/pole-resistance test.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0bdf2c3a-1972-5e0f-8a82-05cd9a7dd70e', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '5', 'With the breaker in a test position, perform the following tests:', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2a7a07ed-cf46-5cc8-bf88-70f5115b8779', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '6', 'Perform minimum pickup voltage tests on trip and close coils in accordance with manufacturer’s published data. In the absence of manufacturer’s published data refer to Table 100.20.', true, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('b81afb91-0535-5aa7-9a66-c68e2fed5d53', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '7', 'Perform power-factor or dissipation-factor tests with breaker in both the open and closed positions.', true, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ccdbfdbc-0568-5aa6-9922-f925d827ad93', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '8', 'Perform power-factor or dissipation-factor tests on each bushing equipped with a powerfactor/ capacitance tap. In the absence of a power-factor/ capacitance tap, perform hot-collar tests.  These tests shall be in accordance with the test equipment manufacturer’s published data.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('326c82e4-0464-5be3-9892-4ff58c458bf7', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '9', 'Perform a dielectric withstand voltage test on each phase with the circuit breaker closed and the poles not under test grounded. Test voltage should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.19.', true, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4833c759-1b31-5552-9786-323f576b1d95', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'electrical', '10', 'Verify blowout coil circuit continuity.', false, 9) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
