INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('cbed55d1-bfc9-5ca2-9617-aad5fb1afcda', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'test_value_visual', '1', 'Compare first-trip operation time and trip-coil current waveform to manufacturer’s published data. In the absence of manufacturer''s published data, compare first-trip operation time and trip-coil current waveform to previously obtained results. (7.6.1.3.A.4)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
