INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f0dc6952-c199-5aeb-aecd-da3f6806a9cd', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'test_value_visual', '4', 'Results of the thermographic survey shall be in accordance with Section 9. (7.6.1.3.A.11.3)', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
