INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c483ce2d-2f5b-59ae-a05d-7dc867bb40ac', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'test_value_electrical', '2', 'Insulation-resistance values of circuit breakers should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
