INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f9774d63-dabd-5b93-aea0-dc129a314c76', '183941bb-f86a-549c-aa5d-46712a24a78b', 'mts', 'test_value_electrical', '8', 'Power-factor or dissipation-factor and capacitance values should be within ten percent of nameplate rating for bushings. Hot collar tests are evaluated on a milliampere/milliwatt loss basis, and the results should be compared to values of similar bushings.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
