INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('88eb7f8c-af12-5893-b1ab-84f0fd727499', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '1', 'Perform resistance measurements through bolted connections with a low-resistance ohmmeter.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4afd0c03-2259-5db7-b1b1-4285c3b8227f', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '2', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phase-to-ground with circuit-breaker closed, and across each open pole. Test voltage shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
