INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d681fa9f-467d-59ea-87ab-f461d458e207', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '4', 'Perform a dynamic contact/pole resistance test.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('24987156-9015-5d8d-8b14-9cd761745162', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '5', 'Perform insulation-resistance tests on all control wiring with respect to ground. Applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components, follow manufacturer’s recommendation.', true, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d64e8935-e8a7-51e6-bbdc-eae4c99b4d66', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '6', 'Remove a sample of insulating liquid in accordance with ASTM D 923. Sample shall be tested in accordance with the referenced standard.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
