INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('75505e33-6238-51cf-95e3-22a632b0cc3c', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '8', 'Verify correct operation of any auxiliary features such as electrical close and trip operation, trip-free, antipump function.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('cf26bf48-1ea9-5146-8382-86a223dad92c', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'electrical', '9', 'Trip circuit breaker by operation of each protective device. Reset all trip logs and indicators.', false, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
