INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e03864ed-b5f8-5761-95e0-3903fc25bc71', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'test_value_visual', '4', 'Contact timing values shall be in accordance with manufacturer’s published data. (7.6.2.A.14).', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
