INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1040dd25-1ada-517b-8ef0-ac8941ddddb7', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('feb26050-3c37-5eda-bece-10353704365d', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'test_value_electrical', '2', 'Insulation-resistance values of circuit breakers shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('96bec2ee-c6f4-56ce-aff2-c67ba9de0c98', '2821a96a-e240-5758-8b11-d6a5df792c75', 'ats', 'test_value_electrical', '3', 'Contact-resistance values shall not exceed the high levels of the normal range as indicated in the manufacturer’s published data. If manufacturer’s published data is not available, investigate values that deviate from adjacent poles or similar breakers by more than 50 percent of the lowest value.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
