INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f64685e7-c798-591c-b845-bd65dc26e05d', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '1', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phase-to-ground with the circuit breaker closed, and across each open pole. Test voltage shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('8f4ef019-6dbd-5649-8ebe-030f54a1f707', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '2', 'Perform insulation-resistance tests on all control wiring with respect to ground. Applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components, follow manufacturer’s recommendation.', true, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d96f96f8-d59a-5196-9cfb-091f638bd785', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '3', 'Perform a contact/pole-resistance test.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ea605913-48fb-59c6-8070-fed18e1f4484', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '4', 'Perform minimum pickup voltage tests on trip and close coils in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.20.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('af8f05a2-c76b-5f28-affd-f91945436f1f', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '5', 'Verify correct operation of any auxiliary features such as electrical close and trip operation, trip-free, and antipump function.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('b28d78f2-3b55-5250-a7d4-61a8d5c4b7d6', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '6', 'Trip circuit breaker by operation of each protective device. Reset all trip logs and indicators.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ded6cc21-a97d-5876-a41c-0758d9e714bf', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '7', 'Perform power-factor or dissipation-factor tests on each pole with the breaker open and each phase with the breaker closed.', true, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d3f448bb-044c-5bc8-b1c2-d9f58762677d', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '8', 'Perform power-factor or dissipation-factor tests on each bushing equipped with a power-factor/capacitance tap. In the absence of a power-factor/capacitance tap, perform hot-collar tests. These tests shall be in accordance with the test equipment manufacturer’s published data.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('141ece8c-2d24-5abc-889d-597f238eae1f', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '9', 'Perform magnetron atmospheric condition (MAC) test on each vacuum interrupter.', true, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('7a364902-da37-56d6-bd59-6ba295ac9e09', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '10', 'Perform vacuum bottle integrity (dielectric withstand voltage) test across each vacuum bottle with the breaker in the open position in strict accordance with manufacturer’s published data.', false, 9) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ece9cd7f-a0be-5284-a859-7674ac97f919', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '11', 'Perform a dielectric withstand voltage test in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.19.', false, 10) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('476fc13b-6104-51c4-95e0-0a2a2ea8fe17', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '12', 'Verify operation of heaters.', false, 11) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('03dd0892-2538-5924-9096-102710a356b7', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'electrical', '13', 'Test instrument transformers in accordance with Section 7.10.', false, 12) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4614981f-f109-545f-a973-25e543411df7', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '1', 'Critical distance measurements such as contact gap shall be in accordance with the manufacturer’s published data. (7.6.3.A.7)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('6bc34205-21ed-5b33-8445-d7c6a55f18bc', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '2', 'Bolt-torque levels shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.12. (7.6.3.A.8)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('303d4208-e4db-5706-8368-3bf7b763c932', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '3', 'Results of the thermographic survey shall be in accordance with Section 9. (7.6.3.A.16)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('cacdc190-39c8-5bad-84db-36345db1126e', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '4', 'Contact timing values shall be in accordance with manufacturer’s published data. (7.6.3.A.12)', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
