INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f632855b-f165-5eea-b88b-a7b294a19043', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '6', 'Travel and velocity values shall be in accordance with manufacturer’s published data. (7.6.3.A.14)', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('cb7ad677-535b-512e-8ca2-cf34b590fb96', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_visual', '7', 'Operation counter shall advance one digit per close-open cycle. (7.6.3.A.15)', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d4957113-1a21-5520-b26b-b463eb14e4db', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '1', 'Insulation-resistance values of circuit breakers shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.1. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('7fdee373-e947-5f08-88cc-40e7dac53429', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '2', 'Insulation-resistance values of control wiring shall not be less than two megohms.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('8bdebe6a-aa77-5d5d-a4de-3272cb639987', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '3', 'Contact-resistance values shall not exceed the high levels of the normal range as indicated in the manufacturer’s published data. In the absence of manufacturer’s data, investigate values that deviate from adjacent poles or similar breakers by more than 50 percent of the lowest value.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e9d93b81-290b-5d57-a18b-25554db8061b', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '4', 'Minimum pickup voltage of the trip and close coils shall conform to the manufacturer’s published data. In the absence of the manufacturer’s published data, refer to Table 100.20.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('eb54a1cc-02c7-5167-92b4-b6aca8b385ad', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '5', 'Auxiliary features shall operate in accordance with manufacturer’s published data.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ec283fd6-78ee-5432-8aa1-b565f21f4dee', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '6', 'Protective devices shall operate the breaker per system design.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('728e56be-23bb-5ccf-ab67-658a515617b0', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '7', 'Power-factor or dissipation-factor values shall be compared to manufacturer’s published data. In the absence of manufacturer’s data the comparison shall be made to similar breakers.', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('9dda12cb-8565-5c75-94ce-66195702a7af', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '8', 'Power-factor or dissipation-factor and capacitance values shall be within ten percent of nameplate rating for bushings. Hot collar tests are evaluated on a milliampere/milliwatt loss basis, and the results should be compared to values of similar bushings.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3c97b7da-7533-5aea-9183-6de38809d03c', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '9', 'In the absence of manufacturer’s published data, each vacuum interrupter pressure shall not be greater than 1x10-2 Pa and shall not deviate from adjacent poles by more than two orders of magnitude.', false, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c3861108-e79f-5804-b6fb-0ae1d27ea339', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '10', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the vacuum bottle integrity test, the test specimen is considered to have passed the test.', false, 9) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2d2d84bb-2dfc-5013-b559-a301b76c0160', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '11', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the dielectric withstand test, the test specimen is considered to have passed the test.', false, 10) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d0ce6b72-a2d2-5268-a005-f8c92df4e583', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '12', 'Heaters shall be operational.', false, 11) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e63fb3fc-6fc7-50b9-98bf-163321007aaf', '684fa354-fc70-56a3-96aa-ae3afd18bd58', 'ats', 'test_value_electrical', '13', 'Results of instrument transformer tests shall be in accordance with Section 7.10. ---', false, 12) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
