INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('3c24eb80-76f9-5950-a244-fd98b8660d92', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'ats', 'electrical', '8', 'Trip circuit breaker by operation of each protective device.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
