INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('499651c3-8518-5adb-89cd-ea56fd441a5a', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '1', 'Perform resistance measurements through all bolted connections with a low-resistance ohmmeter in accordance with Section 7.6.4.A.13.1.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('13b9f74a-efd7-59a1-8e62-e5a56865350b', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '2', 'Perform insulation-resistance tests for one minute on each pole, phase-to-phase and phaseto-ground with breaker closed, and across each open pole. For single-tank breakers, perform insulation resistance tests from pole-to-pole. Apply voltage in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.1.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
