INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('ad924cbb-4bb2-5dd9-8145-fae67b585f7d', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '4', 'Perform a dynamic contact/pole resistance test.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('968a73c1-4355-51b0-bae0-11da890db5e4', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '5', 'Perform insulation-resistance tests on all control wiring with respect to ground. The applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components or for control devices that cannot tolerate the voltage, follow manufacturer’s recommendation.', true, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2f79f457-1bd4-57b2-b88c-cfaf48b3886b', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '6', 'With breaker in a test position, perform the following tests:', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
