INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('41f3cc48-c9cc-5cd2-ac71-705255f908e4', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '8', 'Perform power-factor or dissipation-factor tests on each bushing equipped with a powerfactor/capacitance tap. In the absence of a power-factor/ capacitance tap, perform hot-collar tests.  These tests shall be in accordance with the test equipment manufacturer’s published data.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('e2b41961-c70c-5784-9d49-ffa4d3c63f3e', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'electrical', '9', 'Perform a dielectric withstand voltage test in accordance with manufacturer’s published data.', true, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
