INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('42eef249-b2ba-59ab-a7c4-af0f109272f9', '48016d22-ca2b-5fe3-aeec-01ecb7dc52b5', 'mts', 'test_value_electrical', '8', 'Power-factor or dissipation-factor and capacitance test values should be within ten percent of nameplate rating for bushings. Hot collar tests are evaluated on a milliampere/milliwatt loss basis, and the results should be compared to values of similar bushings.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
