INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('bbac3b82-cb7c-5337-809b-56bd5071dadc', 'e6b99477-32ea-58a1-998e-d04cc5744e96', 'ats', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
