INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('4b2eb3fc-68e3-5710-8136-17b969565226', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '1', 'Auxiliary devices should operate in accordance with system design. (7.12.1.1.A.7)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0bfa39a6-497f-565c-99f9-88af4db7ff2d', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '2', 'Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.12. (7.12.1.1.A.10)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1044183a-740a-5fb8-b8e7-87e59de091c6', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '3', 'Results of the thermographic survey shall be in accordance with Section 9. (7.12.1.1.A.16)', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f982462a-37b5-5d0f-996f-f25baf8553fd', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '4', 'Motor, drive train, and automatic cutoff should operate in accordance with manufacturer’s design. (7.12.1.1.A.11)', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('151f12a7-2a27-50dd-be85-f4326545a8dd', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '5', 'Liquid level in tanks and bushings should be within indicated tolerances. (7.12.1.1.A.13)', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c93be60c-a30a-50fe-a412-7227d5b1754e', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_visual', '6', 'The operation counter shall move incrementally for each operation performed. (7.12.1.1.A.13)', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('47c57102-771f-5c7a-b089-7ced6a036af5', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_electrical', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value.', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('97a42532-d356-5695-b2db-75264d709bf3', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_electrical', '2', 'Insulation-resistance values shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, use Table 100.5. Values of insulation resistance less than this table or manufacturer’s recommendations should be investigated. Resistance values shall be temperature corrected in accordance with Table 100.14. The polarization index shall be compared to manufacturer’s factory test results. If manufacturer’s test results are not available the polarization index value shall not be less than 1.0.', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('1935f110-65a8-500c-a8a5-833ae0555c80', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_electrical', '3', 'Maximum power-factor or dissipation-factor values of liquid-filled regulators shall be in accordance with manufacturer’s published data. In the absence of manufacturer’s data, compare to test equipment manufacturer’s published data. Representative-values are indicated in Table 100.3.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('c17cee21-816d-56de-bb8a-2a5df8c830ac', '3a763216-5339-5a94-83d6-1fa843ff733d', 'ats', 'test_value_electrical', '4', 'Power-factor or dissipation-factor and capacitance values shall be within ten percent of nameplate rating for bushings. Hot collar tests are evaluated on a milliampere/milliwatt loss basis, and the results shall be compared to values of similar bushings.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
