INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('5fbb33ac-c40c-526f-b0e9-8fccbdb3d6b3', 'db5be530-1d18-52d4-830c-57a0a02f131d', 'mts', 'test_value_electrical', '15', 'Investigate cause if current signature analysis tests show evidence of cracks or breaks in squirrel-cage windings, non-uniform air gaps, rolling element bearing defects, etc. Sideband magnitudes less than 40 dB from the power frequency are considered indicators of broken bars, whereas magnitudes less than 60 dB may be a warning of a developing problem. NonNETA uniform air gaps may be present when the average of the difference between the current magnitudes of the side frequencies from the highest magnitude frequency component are less than 15 dB, and a warning if less than 25 dB.', false, 14) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
