INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0c7cbc86-a010-56a1-8ee1-8bd7a3ee336e', '6ffbb3ba-a0be-5b18-b7d4-a84a8d2bdd85', 'mts', 'test_value_electrical', '25', 'Investigate cause if current signature analysis tests show evidence of non-uniform air gaps, rolling element bearing defects, etc. Sideband magnitudes less than 40 dB from the power frequency are considered indicators of broken bars, whereas, magnitudes of less than 60 dB may be a warning of a developing problem. Non-uniform air gaps may be present when the average of the difference between the current magnitudes of the side frequencies from the highest magnitude frequency component are less than 15 dB, and a warning if less than 25 dB.', false, 24) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
