INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('2a69b616-80ce-55a8-ab5f-061e30e93104', '7c74db5e-f51b-50e4-9394-007dfdc62add', 'mts', 'test_value_electrical', '3', 'IR 1 min = 5 megohms for most machines and random-wound stator coils and formwound coils rated below 1 kV and dc armatures. NOTE: Dielectric withstand voltage, high-potential, and surge comparison tests shall not be performed on machines having values lower than those indicated above.', false, 2) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f63cab00-3293-545d-be5a-112b3c1384e1', '7c74db5e-f51b-50e4-9394-007dfdc62add', 'mts', 'test_value_electrical', '4', 'The individual pole-to-pole AC voltage drop shall not exceed ten percent variance from the average value (average value = test voltage divided by number of coils) applicable to all of the poles.', false, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
