INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('9fc41202-6b30-59b4-b917-1b3b4d874cbe', 'c2160052-5d85-5125-aa5a-d96b2e7e43a4', 'mts', 'test_value_visual', '1', 'Compare bolted connection resistance values to values of similar connections. Investigate values which deviate from those of similar bolted connections by more than 50 percent of the lowest value. (7.16.1.2.A.5.1)', false, 0) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('809e0286-722c-5fa0-9dcd-7df5bcc3ae08', 'c2160052-5d85-5125-aa5a-d96b2e7e43a4', 'mts', 'test_value_visual', '2', 'Bolt-torque levels should be in accordance with manufacturer’s published data. In the absence of manufacturer’s published data, use Table 100.12. (7.16.1.2.A.5.2)', false, 1) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
