INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('184e6adc-09f0-5189-87a1-7096b7af0ecc', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'electrical', '4', 'Perform insulation-resistance tests on all control wiring with respect to ground. Applied potential shall be 500 volts dc for 300-volt rated cable and 1000 volts dc for 600-volt rated cable. Test duration shall be one minute. For units with solid-state components, follow manufacturer’s recommendation.', true, 3) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('d4dde252-8c97-50ef-9c69-4311e761b5b3', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'electrical', '5', 'Remove a sample of insulating liquid in accordance with ASTM D 923. Sample shall be tested in accordance with the referenced standard.', false, 4) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
