INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('7ceae599-4aa9-5661-b622-bf7de3578a7b', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'electrical', '8', 'Perform power-factor or dissipation-factor tests on each bushing equipped with a power-factor/capacitance tap. In the absence of a power-factor/capacitance tap, perform hot-collar tests. These tests shall be in accordance with the test equipment manufacturer’s published data.', true, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
