INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('0dc10c3c-d413-53d0-b6ec-ea60402c1677', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'test_value_electrical', '6', 'Minimum pickup voltage of the trip and close coils shall conform to the manufacturer’s published data. In the absence of the manufacturer’s published data, use Table 100.20.', false, 5) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('81b9d7a7-3746-56cd-ac1d-9a5eec4eb4b8', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'test_value_electrical', '7', 'Power-factor or dissipation-factor values and tank loss-index shall be compared to manufacturer’s published data. In the absence of manufacturer’s published data, the comparison shall be made to test data from similar circuit reclosers or data from test equipment manufacturers.', false, 6) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('fbac5384-36a9-5813-af68-11f3477bfa37', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'test_value_electrical', '8', 'Power-factor or dissipation-factor and capacitance values shall be within ten percent of nameplate rating for bushings. Hot collar tests are evaluated on a milliampere/milliwatt loss basis, and the results shall be compared to values of similar bushings.', false, 7) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('f25e78b0-c6cc-55ec-8c89-b58c5208436f', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'test_value_electrical', '9', 'In the absence of manufacturer’s published data, each vacuum interrupter pressure shall not be greater than 1x10-2 Pa and shall not deviate from adjacent poles by more than two orders of magnitude.', false, 8) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
INSERT INTO records.neta_test_items (neta_test_item_id, neta_procedure_id, standard, category, item_number, description, is_optional, sort_order) VALUES ('9aa224ee-484d-5e4b-8507-d3e180bfe269', 'b73ef044-907a-5aa9-a514-3d2af7df5ffd', 'ats', 'test_value_electrical', '10', 'If no evidence of distress or insulation failure is observed by the end of the total time of voltage application during the vacuum bottle integrity test, the test specimen is considered to have passed the test.', false, 9) ON CONFLICT (neta_procedure_id, standard, category, item_number) DO UPDATE SET description=EXCLUDED.description, is_optional=EXCLUDED.is_optional, sort_order=EXCLUDED.sort_order;
